function validate([jobs, k]) {
  if (!Array.isArray(jobs) || jobs.length < 1 || jobs.length > 12) return 'jobs needs 1 to 12 values.';
  if (jobs.some(v => !Number.isInteger(v) || v < 1 || v > 10000000)) return 'Each job takes from 1 to 10^7.';
  if (!Number.isInteger(k) || k < 1 || k > jobs.length) return 'k is between 1 and jobs.length.';
  return null;
}

