function minimumTimeRequired(jobs, k) {
  const sorted = [...jobs].sort((a, b) => b - a);
  const loads = new Array(k).fill(0);
  let best = sorted.reduce((sum, job) => sum + job, 0);

  const assign = (index, maxLoad) => {
    if (maxLoad >= best) {
      return;
    }
    if (index === sorted.length) {
      best = maxLoad;
      return;
    }
    const tried = new Set();
    for (let worker = 0; worker < k; worker++) {
      if (tried.has(loads[worker])) {
        continue;
      }
      tried.add(loads[worker]);
      loads[worker] += sorted[index];
      assign(index + 1, Math.max(maxLoad, loads[worker]));
      loads[worker] -= sorted[index];
    }
  };

  assign(0, 0);
  return best;
}

