function minimumTimeRequired(jobs, k) {
  // Subset DP: dp[mask] = best maximum when the jobs in mask are split among w workers.
  const n = jobs.length, full = (1 << n) - 1;
  const total = new Array(1 << n).fill(0);
  for (let mask = 1; mask <= full; mask++) {
    const low = mask & -mask;
    total[mask] = total[mask ^ low] + jobs[31 - Math.clz32(low)];
  }
  let dp = total.slice();
  for (let w = 2; w <= k; w++) {
    const next = dp.slice();
    for (let mask = 1; mask <= full; mask++)
      for (let part = mask; part; part = (part - 1) & mask)
        next[mask] = Math.min(next[mask], Math.max(total[part], dp[mask ^ part]));
    dp = next;
  }
  return dp[full];
}

