function generate(rand, size) {
  const n = size === 'large' ? 12 : 1 + Math.floor(rand() * 8);
  const k = 1 + Math.floor(rand() * n);
  const spans = [3, 10, 100, 10000000];
  const span = spans[Math.floor(rand() * spans.length)];
  const jobs = Array.from({ length: n }, () => 1 + Math.floor(rand() * span));
  return [jobs, k];
}
